SELECT CAST(date_format(first_installed,'yyyyMMdd') AS long) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,cdr_source_path ,filter_dtm ,create_by ,process_date ,status, b_no ,mapping_error ,err_msg ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,source_path AS cdr_source_path ,filter_dtm ,create_by ,now() as process_date ,status, b_no ,mapping_error ,mapping_error_msg AS err_msg ,workflow_process_date,file_date FROM tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM tb_transaction_ss_esim_temp WHERE workflow_process_date = (SELECT  workflow_process_date FROM tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'UNMAP' AND chk_dup_append = 0 )